--region lifecycle
---@override
function ActivityTabToggleLeftCell:Awake()
    self.super.Awake(self)
    self:PlayAnimation()
end

---@override
function ActivityTabToggleLeftCell:FreshSelectStatus(isSelected)
    KTool.SetActive(self.Image, isSelected)
    CfUtils.SetUISwitchText(self.Text.transform, isSelected and SwitchTextStatusEnum.SELECTED or SwitchTextStatusEnum.DEFAULT)


    if isSelected then
        CfUtils.SetColor(self.ImgIcon, XLuaUtils.HexToColor("#666666"))
        CfUtils.SetScale(self.ImgIcon, Vector3(0.5, 0.5, 1))
        --self.redPoint.transform.anchoredPosition = Vector3(50, 15, 0)
    else
        CfUtils.SetColor(self.ImgIcon, XLuaUtils.HexToColor("#a3a3a3"))
        CfUtils.SetScale(self.ImgIcon, Vector3(0.4, 0.4, 1))
        --self.redPoint.transform.anchoredPosition = Vector3(46, 15, 0)
    end
end
--endregion lifecycle

--region inheritance
---@override
function ActivityTabToggleLeftCell:FreshBaseUI(data)
    self.Text.text = data.dojo.name
    local isHideDay = ActivityConstants.IsHideDay(data.dojo.type) -- 是否要专门隐藏这个活动的 左侧栏的 日期显示
    if isHideDay then
        if checkInt(data.dojo.endTime) - os.time() > 86400000  then
            KTool.SetActive(self.TextDay, data.dojo.endTime ~= nil and (isHideDay==false) )     
        end
    end
    if data.dojo.endTime ~= nil then
        self.TextDay.text = ActivityUtils.ConventLeftTimeText(data.dojo.endTime)
    end

    if data.dojo.redNode ~= nil then
        GameUtils.BindRedPoint(data.dojo.redNode, self.TextTitle, true)
    else
        if checkInt(data.dojo.redDotHint) == 0 then
            KTool.SetActive(self.redPoint, true)
        else
            KTool.SetActive(self.redPoint, ActivityMgr:GetActivityExtraRedPointState(data.dojo.type, data.dojo.id) == 0)
        end
    end

    local urgency = ActivityUtils.IsUrgentTime(data.dojo.endTime)
    if urgency then
        CfUtils.SetUISwitchText(self.TextDay, TextDayStatusEnum.URGENCY)
    else
        CfUtils.SetUISwitchText(self.TextDay, data.isSelected and TextDayStatusEnum.SELECTED or TextDayStatusEnum.DEFAULT)
    end
end
--endregion inheritance

--region public
---刷新icon
---@param path string icon路径
function ActivityTabToggleLeftCell:FreshIcon(path)
    CfUtils.FillImage(self.ImgIcon.gameObject, path)
    CfUtils.FillImage(self.ImgIconShadow.gameObject, path)
end
---播放选中动画
function ActivityTabToggleLeftCell:PlayAnimation()
    CfUtils.PlayAnimator(self.AnimRoot, "Go")
end
